[CmdletBinding()]
param([Parameter(Mandatory=$true)][string]$ClientRoot)
Set-StrictMode -Version Latest
$ErrorActionPreference='Stop'
function Safe([string]$root,[string]$relative){if([IO.Path]::IsPathRooted($relative)-or$relative.Contains('..')-or$relative.StartsWith('\\')){throw 'Unsafe contract path.'};$p=[IO.Path]::GetFullPath((Join-Path $root $relative));if(-not$p.StartsWith($root.TrimEnd('\')+'\',[StringComparison]::OrdinalIgnoreCase)){throw 'Contract path escaped client root.'};$p}
& (Join-Path $PSScriptRoot 'Verify-OwnerTestIntegrity.ps1') -PackageDirectory $PSScriptRoot
$contract=Get-Content (Join-Path $PSScriptRoot 'install-contract.json') -Raw -Encoding UTF8|ConvertFrom-Json
$root=[IO.Path]::GetFullPath($ClientRoot).TrimEnd('\');if(-not[IO.Directory]::Exists($root)){throw 'Client root is unavailable.'};if((Get-Item $root -Force).Attributes-band[IO.FileAttributes]::ReparsePoint){throw 'Client root cannot be a reparse point.'}
foreach($e in $contract.preflight){$p=Safe $root $e.relativePath;if((Get-FileHash -LiteralPath $p -Algorithm SHA256).Hash-ne$e.sha256){throw "Preflight mismatch: $($e.relativePath)"}}
if(@(Get-Process PlayRevora.Launcher,play,AutoP,Conquer -ErrorAction SilentlyContinue).Count){throw 'Launcher and game processes must be closed.'}
$tx='owner-test-a-'+[Guid]::NewGuid().ToString('N');$state=Safe $root 'RevoraUpdates\State';$rollback=Safe $root ('RevoraUpdates\Rollback\'+$tx);[IO.Directory]::CreateDirectory($state)|Out-Null;[IO.Directory]::CreateDirectory($rollback)|Out-Null
$pending=Join-Path $state 'owner-test-a.pending';[IO.File]::WriteAllText($pending,$tx,[Text.UTF8Encoding]::new($false));$done=New-Object Collections.Generic.List[object]
try{foreach($e in $contract.files){$source=Safe (Join-Path $PSScriptRoot 'payload') $e.relativePath;$target=Safe $root $e.relativePath;$parent=Split-Path $target -Parent;[IO.Directory]::CreateDirectory($parent)|Out-Null;if((Get-Item $parent -Force).Attributes-band[IO.FileAttributes]::ReparsePoint){throw 'Target parent cannot be a reparse point.'};$backup=Safe $rollback $e.relativePath;[IO.Directory]::CreateDirectory((Split-Path $backup -Parent))|Out-Null;$existed=[IO.File]::Exists($target);if($existed){Copy-Item -LiteralPath $target -Destination $backup};$temp=$target+'.revora-new';Copy-Item -LiteralPath $source -Destination $temp -Force;if((Get-FileHash $temp -Algorithm SHA256).Hash-ne$e.sha256){throw "Payload mismatch: $($e.relativePath)"};if($existed){$replaceBackup=$target+'.revora-replaced';[IO.File]::Replace($temp,$target,$replaceBackup);Remove-Item $replaceBackup -Force}else{Move-Item -LiteralPath $temp -Destination $target};$done.Add([pscustomobject]@{relativePath=$e.relativePath;existed=$existed;sha256=$e.sha256})}
$receipt=[ordered]@{schemaVersion=1;transactionId=$tx;variant='D3D9On12 OWNER-TEST';files=$done.ToArray()};[IO.File]::WriteAllText((Join-Path $state 'owner-test-a-installed.json'),($receipt|ConvertTo-Json -Depth 6),[Text.UTF8Encoding]::new($false));Remove-Item -LiteralPath $pending -Force;Write-Host 'D3D9On12 OWNER-TEST A installed transactionally.' -ForegroundColor Green
}catch{$completed=$done.ToArray();[array]::Reverse($completed);foreach($e in $completed){$target=Safe $root $e.relativePath;$backup=Safe $rollback $e.relativePath;if($e.existed){Copy-Item $backup ($target+'.restore') -Force;[IO.File]::Replace(($target+'.restore'),$target,($target+'.failed'))}elseif([IO.File]::Exists($target)){Remove-Item $target -Force}};Remove-Item $pending -Force -ErrorAction SilentlyContinue;throw}
